html:
{%- set quals = [] -%}
{%- for r in doc.diamond_rates -%}{%- if (r.quality or "") not in quals -%}{%- set _ = quals.append(r.quality or "") -%}{%- endif -%}{%- endfor -%}
{%- set brackets = [] -%}
{%- for r in doc.diamond_rates -%}{%- set key = (r.sieve_label or "", r.from_ct or 0, r.to_ct or 0) -%}{%- if key not in brackets -%}{%- set _ = brackets.append(key) -%}{%- endif -%}{%- endfor -%}
<style>
.rc{font-family: Georgia, 'Times New Roman', serif; color:#222; font-size:13px; line-height:1.45;}
.rc h1{text-align:center; font-size:19px; letter-spacing:2px; margin:0 0 2px;}
.rc .date{text-align:right; font-size:12px;}
.rc .qline{margin:10px 0 2px; font-weight:bold;}
.rc table{border-collapse:collapse; width:100%; margin:6px 0 14px;}
.rc th, .rc td{border:1px solid #999; padding:4px 8px; font-size:12px;}
.rc th{background:#f3efe4; text-align:left;}
.rc td.r, .rc th.r{text-align:right;}
.rc .sec{font-weight:bold; text-decoration:underline; margin:14px 0 4px;}
.rc .kv td{border:none; padding:2px 8px 2px 0;}
.rc .terms{margin-top:16px; font-size:12px; white-space:pre-line;}
.rc .sign{margin-top:26px;}
</style>
<div class="rc">
<h1>RATE CHART{% if doc.chart_name %} - {{ doc.chart_name | upper }}{% endif %}</h1>
<div class="date">Date: {{ frappe.utils.formatdate(doc.chart_date, "dd-MM-yyyy") }}</div>

{% if doc.diamond_quality_note %}<div class="qline">Diamond Purity: {{ doc.diamond_quality_note }}</div>{% endif %}
{% if doc.gold_purity_factor %}<div><b>GOLD PURITY {{ doc.gold_purity_factor }}</b></div>{% endif %}

{% if doc.diamond_rates %}
<div class="sec">DIAMOND CENTS</div>
<table>
<tr><th>Sieve</th><th>Per-stone weight</th>{% for q in quals %}<th class="r">{{ q or "RATE" }} (₹/ct)</th>{% endfor %}</tr>
{% for b in brackets %}
<tr>
<td>{{ b[0] }}</td>
<td>{% if b[2] %}From {{ b[1] }} to below {{ b[2] }} cts{% else %}{{ b[1] }} cts and above{% endif %}</td>
{% for q in quals %}{% set ns = namespace(rate="") %}{% for r in doc.diamond_rates %}{% if (r.sieve_label or "", r.from_ct or 0, r.to_ct or 0) == b and (r.quality or "") == q %}{% set ns.rate = r.rate %}{% endif %}{% endfor %}<td class="r">{{ "{:,.0f}".format(ns.rate) if ns.rate != "" else "—" }}</td>{% endfor %}
</tr>
{% endfor %}
</table>
{% endif %}

<table class="kv">
{% if doc.colour_stone_rate %}<tr><td>All Colour Stone</td><td><b>₹{{ "{:,.0f}".format(doc.colour_stone_rate) }} / ct</b></td></tr>{% endif %}
{% if doc.precious_stone_rate %}<tr><td>Precious Stone</td><td><b>₹{{ "{:,.0f}".format(doc.precious_stone_rate) }} / ct</b></td></tr>{% endif %}
{% if doc.job_work_pty_rate %}<tr><td>JOB WORK — PTY DIAMOND</td><td><b>₹{{ "{:,.0f}".format(doc.job_work_pty_rate) }} / ct</b></td></tr>{% endif %}
</table>

{% if doc.making_rules %}
<div class="sec">Making Charges</div>
<table>
<tr><th>Applies To</th><th>Basis</th><th class="r">Rate</th><th class="r">Minimum / pc</th></tr>
{% for r in doc.making_rules %}
<tr>
<td>{{ r.design_type or r.charge_category or "All items" }}</td>
<td>{{ r.basis }}</td>
<td class="r">{% if r.basis == "Purity Percent" %}{{ r.rate }} %{% else %}₹{{ "{:,.0f}".format(r.rate) }}{% endif %}</td>
<td class="r">{{ "₹{:,.0f}".format(r.min_per_piece) if r.min_per_piece else "—" }}</td>
</tr>
{% endfor %}
</table>
{% endif %}

{% if doc.setting_rates %}
<div class="sec">Setting Charges (per stone)</div>
<table>
<tr><th>Stone size (ct)</th><th class="r">₹ / stone</th></tr>
{% for r in doc.setting_rates %}<tr><td>{{ r.stone_ct }}</td><td class="r">{{ "{:,.0f}".format(r.rate) }}</td></tr>{% endfor %}
</table>
{% endif %}

{% if doc.special_works %}
<div class="sec">Special Works</div>
<table>
<tr><th>Work</th><th>Basis</th><th class="r">Rate</th></tr>
{% for r in doc.special_works %}<tr><td>{{ r.work_name }}</td><td>{{ r.basis }}</td><td class="r">₹{{ "{:,.0f}".format(r.rate) }}</td></tr>{% endfor %}
</table>
{% endif %}

{% if doc.hallmark_charge or doc.certification_charge %}
<table class="kv">
{% if doc.hallmark_charge %}<tr><td>Hallmarking</td><td><b>₹{{ "{:,.0f}".format(doc.hallmark_charge) }} / pc</b></td></tr>{% endif %}
{% if doc.certification_charge %}<tr><td>Certification</td><td><b>₹{{ "{:,.0f}".format(doc.certification_charge) }} / pc</b></td></tr>{% endif %}
</table>
{% endif %}

{% if doc.payment_terms %}<div class="sec">Payment Terms</div><div class="terms">{{ doc.payment_terms }}</div>{% endif %}

<div class="sec">Our Terms and Conditions Follow</div>
<div class="terms">{{ doc.terms or "" }}</div>

<div class="sign">Thanking you and assuring of our best services.<br><br>
<b>{{ doc.signatory or "" }}</b>{% if doc.signatory_phone %}<br>{{ doc.signatory_phone }}{% endif %}</div>
</div>
